update public.private_life_asset_catalog set active=false,updated_at=now() where category='watch' and code in ('watch_heritage_steel','watch_continental_chrono','watch_riviera_gold','watch_grand_complication','watch_collector_heritage','watch_one_of_one');

on conflict (code) do update set category=excluded.category,name=excluded.name,tier=excluded.tier,description=excluded.description,purchase_price=excluded.purchase_price,prestige=excluded.prestige,rarity=excluded.rarity,annual_running_cost=excluded.annual_running_cost,annual_value_rate_bps=excluded.annual_value_rate_bps,resale_discount_bps=excluded.resale_discount_bps,image_url=excluded.image_url,active=true,metadata=excluded.metadata,updated_at=now();